CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE, owner_id uuid NOT NULL, role text NOT NULL DEFAULT 'admin' CHECK (role IN ('owner','admin')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.team_access(target uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() = target OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND owner_id=target) $$;
CREATE POLICY team_roles_read ON public.user_roles FOR SELECT TO authenticated USING (public.team_access(owner_id));
CREATE POLICY team_data_read ON public.app_data FOR SELECT TO authenticated USING (public.team_access(user_id));
CREATE TABLE public.team_invites (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, email text NOT NULL, code uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE, expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days', accepted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.team_invites TO authenticated; GRANT ALL ON public.team_invites TO service_role;
ALTER TABLE public.team_invites ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_invites ON public.team_invites FOR SELECT TO authenticated USING (auth.uid()=owner_id);
CREATE TABLE public.notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, user_id uuid NOT NULL, event_key text NOT NULL, title text NOT NULL, body text NOT NULL DEFAULT '', path text NOT NULL DEFAULT '/', read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,event_key));
GRANT SELECT, UPDATE ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role;
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY notifications_read ON public.notifications FOR SELECT TO authenticated USING(auth.uid()=user_id AND public.team_access(owner_id));
CREATE POLICY notifications_mark ON public.notifications FOR UPDATE TO authenticated USING(auth.uid()=user_id AND public.team_access(owner_id)) WITH CHECK(auth.uid()=user_id AND public.team_access(owner_id));
CREATE TABLE public.push_devices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, token text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.push_devices TO authenticated; GRANT ALL ON public.push_devices TO service_role;
ALTER TABLE public.push_devices ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_devices ON public.push_devices FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE FUNCTION public.ensure_team() RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; SELECT owner_id INTO o FROM public.user_roles WHERE user_id=auth.uid(); IF o IS NULL THEN INSERT INTO public.user_roles(user_id,owner_id,role) VALUES(auth.uid(),auth.uid(),'owner') ON CONFLICT(user_id) DO NOTHING; SELECT owner_id INTO o FROM public.user_roles WHERE user_id=auth.uid(); END IF; RETURN o; END $$;
CREATE FUNCTION public.invite_admin(invite_email text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid; BEGIN IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND owner_id=auth.uid() AND role='owner') THEN RAISE EXCEPTION 'Owner access required'; END IF; IF invite_email !~ '^[^ @]+@[^ @]+\.[^ @]+$' THEN RAISE EXCEPTION 'Invalid email'; END IF; INSERT INTO public.team_invites(owner_id,email) VALUES(auth.uid(),lower(trim(invite_email))) RETURNING code INTO c; RETURN c; END $$;
CREATE FUNCTION public.accept_admin(invite_code uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.team_invites; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; SELECT * INTO i FROM public.team_invites WHERE code=invite_code AND accepted_at IS NULL AND expires_at>now() FOR UPDATE; IF i.id IS NULL OR i.email<>lower(auth.jwt()->>'email') OR coalesce(auth.jwt()->>'email','')='' THEN RAISE EXCEPTION 'Invitation invalid or belongs to another email'; END IF; IF EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND owner_id<>auth.uid() AND owner_id<>i.owner_id) THEN RAISE EXCEPTION 'Already in another team'; END IF; INSERT INTO public.user_roles(user_id,owner_id,role) VALUES(auth.uid(),i.owner_id,'admin') ON CONFLICT(user_id) DO UPDATE SET owner_id=excluded.owner_id,role='admin'; UPDATE public.team_invites SET accepted_at=now() WHERE id=i.id; RETURN i.owner_id; END $$;
CREATE FUNCTION public.remove_admin(member_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR member_id=auth.uid() THEN RAISE EXCEPTION 'Not allowed'; END IF; DELETE FROM public.user_roles WHERE user_id=member_id AND owner_id=auth.uid() AND role='admin'; END $$;
CREATE FUNCTION public.merge_records(current_rows jsonb, incoming_rows jsonb, base_rows jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=public AS $$ WITH changed AS (SELECT x FROM jsonb_array_elements(coalesce(incoming_rows,'[]')) x WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(base_rows,'[]')) b WHERE b->>'id'=x->>'id' AND b=x)), removed AS (SELECT b->>'id' id FROM jsonb_array_elements(coalesce(base_rows,'[]')) b WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(incoming_rows,'[]')) x WHERE x->>'id'=b->>'id')), kept AS (SELECT x FROM jsonb_array_elements(coalesce(current_rows,'[]')) x WHERE NOT EXISTS(SELECT 1 FROM changed c WHERE c.x->>'id'=x->>'id') AND NOT EXISTS(SELECT 1 FROM removed r WHERE r.id=x->>'id')) SELECT coalesce(jsonb_agg(x),'[]') FROM (SELECT x FROM changed UNION ALL SELECT x FROM kept) all_rows $$;
CREATE FUNCTION public.save_team_data(target uuid, incoming jsonb, baseline jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE current_data jsonb; merged jsonb; k text; BEGIN IF NOT public.team_access(target) THEN RAISE EXCEPTION 'Forbidden'; END IF; INSERT INTO public.app_data(user_id,data) VALUES(target,incoming) ON CONFLICT(user_id) DO NOTHING; SELECT data INTO current_data FROM public.app_data WHERE user_id=target FOR UPDATE; merged:=current_data; FOREACH k IN ARRAY ARRAY['invoices','customers','products','sales','designs','activity','parcels','closures'] LOOP merged:=jsonb_set(merged,ARRAY[k],public.merge_records(current_data->k,incoming->k,baseline->k)); END LOOP; IF incoming->'settings' IS DISTINCT FROM baseline->'settings' THEN merged:=jsonb_set(merged,'{settings}',incoming->'settings'); END IF; IF EXISTS(SELECT 1 FROM jsonb_array_elements(merged->'invoices') x GROUP BY x->>'number' HAVING count(*)>1) THEN RAISE EXCEPTION 'Invoice number conflict. Reload and retry.'; END IF; UPDATE public.app_data SET data=merged,updated_at=now() WHERE user_id=target; RETURN merged; END $$;
CREATE FUNCTION public.notify_team(target uuid, key text, heading text, message text, link text, actor uuid DEFAULT NULL) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ INSERT INTO public.notifications(owner_id,user_id,event_key,title,body,path) SELECT target,user_id,key,heading,message,link FROM public.user_roles WHERE owner_id=target AND (actor IS NULL OR user_id<>actor) ON CONFLICT(user_id,event_key) DO NOTHING $$;
REVOKE ALL ON FUNCTION public.notify_team(uuid,text,text,text,text,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.notify_team(uuid,text,text,text,text,uuid) TO service_role;
CREATE FUNCTION public.team_data_events() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE x jsonb; BEGIN FOR x IN SELECT a FROM jsonb_array_elements(coalesce(NEW.data->'activity','[]')) a WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(OLD.data->'activity','[]')) b WHERE b->>'id'=a->>'id') LOOP PERFORM public.notify_team(NEW.user_id,'activity:'||(x->>'id'),x->>'action',x->>'ref','/activity',auth.uid()); END LOOP; RETURN NEW; END $$;
CREATE TRIGGER team_data_event_trigger AFTER UPDATE ON public.app_data FOR EACH ROW EXECUTE FUNCTION public.team_data_events();
REVOKE ALL ON FUNCTION public.ensure_team(),public.invite_admin(text),public.accept_admin(uuid),public.remove_admin(uuid),public.save_team_data(uuid,jsonb,jsonb),public.team_access(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.ensure_team(),public.invite_admin(text),public.accept_admin(uuid),public.remove_admin(uuid),public.save_team_data(uuid,jsonb,jsonb),public.team_access(uuid) TO authenticated;
CREATE INDEX notifications_user_time ON public.notifications(user_id,created_at DESC);